import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import { ModalServiceContext } from './../../../ricos-context/modal-context.js';
import type { Gradient } from './../../../ricos-types/color-palette-types.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import {
  handleColorAdded,
  handleColorDeleted,
  handleGradientAdded,
  handleGradientDeleted,
  resolveThemeColorsPalette,
  useResolvedCustomColors,
  useResolvedCustomGradients,
} from './../../../_shared/color-manager-utils.js';
import { TRANSPARENT_HEX_COLOR } from './../../../_shared/colors.js';
import { PmNodeType } from './../../../_shared/pm-node-types.js';
import { resolveImageOverlay } from './../../../_shared/resolve-image-overlay.js';
import { useNodeAttrs } from './../../../_shared/use-node-attrs.js';
import { NewColorPicker } from './../../../ui-components/color-picker/new-color-picker/index.js';

import {
  getLayoutFillColor,
  getLayoutFillGradient,
  getLegacyLayoutFillColorKey,
  resolveLayoutFill,
} from '../layout-fill.js';

type LayoutColorPickerProps = {
  modalId: string;
  nodeId: string;
  referenceElement: HTMLDivElement | null;
  colorType:
    | 'backgroundColor'
    | 'borderColor'
    | 'backdropColor'
    | 'topDividerColor'
    | 'bottomDividerColor';
  fallbackColor?: string;
  onValueSelected: (value: { color?: string; gradient?: Gradient } | undefined) => void;
  onColorAdded?: (color: string) => void;
  allowGradient?: boolean;
};

export const LayoutColorPicker: React.FC<LayoutColorPickerProps> = ({
  modalId,
  nodeId,
  referenceElement,
  colorType,
  fallbackColor,
  onValueSelected,
  onColorAdded: onColorAddedProp,
  allowGradient = false,
}) => {
  const modalService = useContext(ModalServiceContext);
  const { t, colorManager, theme } = useContext(RicosContext);

  const { pmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.LAYOUT);

  const logBi = useBiNext({
    modalId,
    pluginId: 'layout',
    nodeId,
  });

  const themeColors = resolveThemeColorsPalette(theme);

  const customColors = useResolvedCustomColors(colorManager);
  const customGradients = useResolvedCustomGradients(colorManager);

  const fillKey =
    colorType === 'backgroundColor'
      ? 'background'
      : colorType === 'backdropColor'
        ? 'backdrop'
        : undefined;
  const currentFill = fillKey
    ? resolveLayoutFill(pmNodeAttrs?.[fillKey], pmNodeAttrs?.[getLegacyLayoutFillColorKey(fillKey)])
    : undefined;

  const dividerKey =
    colorType === 'topDividerColor'
      ? 'topDivider'
      : colorType === 'bottomDividerColor'
        ? 'bottomDivider'
        : undefined;

  const rawCurrentColor = fillKey
    ? (getLayoutFillColor(currentFill) ?? fallbackColor ?? TRANSPARENT_HEX_COLOR)
    : dividerKey
      ? (pmNodeAttrs?.[dividerKey]?.color ?? fallbackColor ?? TRANSPARENT_HEX_COLOR)
      : (pmNodeAttrs?.borderColor ?? TRANSPARENT_HEX_COLOR);

  const fillGradient = getLayoutFillGradient(currentFill);

  // With an image present the picker edits the overlay: the new model `image.overlay` when set,
  // otherwise the legacy fill surfaced through the opacity shim (so the picker's preserve-current-
  // opacity logic sees the effective alpha rather than the underlying 100%).
  const overlayImage = fillKey
    ? pmNodeAttrs?.[fillKey === 'background' ? 'backgroundImage' : 'backdropImage']
    : undefined;
  const overlay = overlayImage
    ? resolveImageOverlay(overlayImage, { gradient: fillGradient, color: rawCurrentColor })
    : undefined;
  const currentColor = overlayImage ? (overlay?.color ?? rawCurrentColor) : rawCurrentColor;
  const currentGradient = overlayImage ? overlay?.gradient : fillGradient;

  const onColorAdded = (color: string) => {
    handleColorAdded(color, colorManager, onColorAddedProp);
    onValueSelected({ color });
  };

  const onGradientAdded = (gradient: Gradient) => {
    handleGradientAdded(gradient, colorManager);
    onValueSelected({ gradient });
  };

  const onGradientDeleted = (gradient: Gradient) => {
    handleGradientDeleted(gradient, colorManager);
  };

  const onColorDeleted = (color: string) => {
    handleColorDeleted(color, colorManager);
  };

  const closeModal = () => modalService.closeModal(modalId);

  const onResetColor = () => onValueSelected(undefined);

  return (
    <NewColorPicker
      themeColors={themeColors}
      customColors={customColors}
      customGradients={allowGradient ? customGradients : undefined}
      currentColor={currentGradient ?? currentColor}
      fallbackColor={currentColor}
      title={t('Layouts_ColourModal_Title')}
      closeModal={closeModal}
      onColorSelected={color => onValueSelected(color ? { color } : undefined)}
      onGradientSelected={gradient => onValueSelected({ gradient })}
      onColorAdded={onColorAdded}
      onColorDeleted={onColorDeleted}
      onGradientAdded={allowGradient ? onGradientAdded : undefined}
      onGradientDeleted={allowGradient ? onGradientDeleted : undefined}
      onResetColor={onResetColor}
      referenceElement={referenceElement}
      logBi={logBi}
      allowTransparent
      allowGradient={allowGradient}
    />
  );
};
