import type { FileSource } from './../../ricos-schema/next-schema/index.js';
import { WIX_SHAPES_BASE_URL } from './../media/media-url-consts.js';

export const getShapeUrl = (src: FileSource, getUrlOverride?: () => string | undefined): string => {
  if (src.url) {
    return src.url;
  }

  if (src.id) {
    const baseUrl = getUrlOverride ? getUrlOverride() : WIX_SHAPES_BASE_URL;
    return `${baseUrl}${src.id}`;
  }

  return '';
};
