/**
 * Per-editor storage for the LAYOUT extension. `draggedCellSourceLayout` holds
 * the id and attrs of the layout a cell was dragged out of, captured at drag
 * start while the cell is still inside its layout. `cell-normalizing` uses it
 * on the drop transaction to (1) wrap the orphaned cell in a layout that keeps
 * the source's styling and (2) remove the now-drained source layout.
 *
 * We deliberately do NOT key by cell id: dropping into a CARD routes through
 * the card-paste `transformPasted` path, which regenerates every node id — so
 * the moved cell no longer matches its original id. The source layout id is
 * preserved (it is not part of the pasted slice), so it stays a reliable key
 * for source removal.
 */
export type LayoutExtensionStorage = {
  draggedCellSourceLayout: { layoutId: string; attrs: Attrs; wasOnlyCell: boolean } | null;
};

export const createEmptyCell = (colSpan: number): PmLayoutCellNode => ({
  type: TIPTAP_LAYOUT_CELL_TYPE,
  attrs: {
    id: generateId(),
    colSpan,
  },
  content: [
    {
      type: Node_Type.PARAGRAPH,
      content: [],
    } as unknown as RicosPmNode,
  ],
});

export const createBlankLayoutData = (
  colCount: number
): PmLayoutNode['attrs'] & { content: PmLayoutNode['content'] } => ({
  ...LAYOUT_DEFAULTS,
  id: generateId(),
  containerData: undefined,
  backgroundColor: undefined,
  backdropColor: undefined,
  backgroundImage: LAYOUT_DEFAULTS.backgroundImage ?? undefined,
  borderColor: LAYOUT_DEFAULTS.borderColor ?? undefined,
  backdropImage: LAYOUT_DEFAULTS.backdropImage ?? undefined,
  banner: LAYOUT_DEFAULTS.banner ?? undefined,
  topDivider: LAYOUT_DEFAULTS.topDivider ?? undefined,
  bottomDivider: LAYOUT_DEFAULTS.bottomDivider ?? undefined,
  cellPadding: [...LAYOUT_DEFAULTS.cellPadding],
  content: Array.from({ length: colCount }, () => createEmptyCell(MAX_COLUMNS / colCount)),
});

export const convertPresetToLayoutData = (
  presetContent: RicosDocument,
  converters: PmConverters
) => {
  const pmContent = converters.toPm(presetContent).content ?? [];
  const layoutNode = pmContent[0];
  if (!layoutNode) {
    return null;
  }
  const { attrs, content } = layoutNode;
  return { ...attrs, content } as PmLayoutNode['attrs'] & { content: PmLayoutNode['content'] };
};

export const balanceLayoutCells = (tr: Transaction, node: PmNode, pos: number) => {
  const colSpan = MAX_COLUMNS / Math.min(node?.childCount ?? MAX_CELLS, MAX_CELLS);

  node?.forEach((_child, childPos) => {
    tr.setNodeAttribute(pos + childPos + 1, 'colSpan', colSpan);
  });
};

export const findLayoutOfCell = (node: ProseMirrorNode, cellId: string): NodeWithPos | null => {
  let maybeLayoutNode: NodeWithPos | null = null;

  node.descendants((child, pos) => {
    if (child.type.name === TIPTAP_LAYOUT_TYPE) {
      for (let i = 0; i < child.childCount; i++) {
        if (child.child(i).attrs.id === cellId) {
          maybeLayoutNode = { node: child, pos };
          break;
        }
      }
    }
  });

  return maybeLayoutNode;
};

export const getParentNodeId = (tr: Transaction, nodeId: string) => {
  const nodeWithPos = findNodeById(tr, nodeId)[0];
  const $pos = tr.doc.resolve(nodeWithPos.pos);
  return $pos.parent.attrs.id;
};

export const getToolbarReferenceElement = (tiptapEditor: Editor) => {
  const $from = tiptapEditor.state.selection.$from;
  const closest = findParentNodeClosestToPos($from, node => node.type.name === TIPTAP_LAYOUT_TYPE);
  const startNodePos = closest ? tiptapEditor.$pos(closest.pos) : $from;
  const nodeElement = tiptapEditor.view.nodeDOM(startNodePos.pos) as HTMLElement | null;

  const handleElement = nodeElement?.querySelector?.('[data-layout-handle]');

  if (nodeElement) {
    return {
      getBoundingClientRect: () => {
        const wrapperRect = nodeElement.getBoundingClientRect();
        const handleElementRect = handleElement?.getBoundingClientRect();
        return new DOMRect(
          wrapperRect.x,
          wrapperRect.y,
          wrapperRect.width,
          wrapperRect.height + (handleElementRect?.height ?? 0) + 4
        );
      },
      contextElement: nodeElement,
    };
  }

  return tiptapEditor.view.nodeDOM(startNodePos.pos - 1) as HTMLElement | null;
};

export const toolbarsToAddIn = [TOOLBARS.FOOTER, TOOLBARS.SIDE, TOOLBARS.MOBILE];

