export const tryParseJson = (value: string | null): Record<string, unknown> | null => {
  if (!value) {
    return null;
  }
  try {
    return JSON.parse(value);
  } catch {
    return null;
  }
};

export const DEFAULT_BACKDROP_VERTICAL_SPACING = 26;
export const DEFAULT_BANNER_VERTICAL_SPACING = 50;

export const createQuickActionBannerLayout = (
  position: 'TOP' | 'BOTTOM' = 'TOP'
): {
  headingId: string;
  layoutNode: PmLayoutNode;
} => {
  const headingId = generateId();
  const { content: _content, ...attrs } = createBlankLayoutData(1);

  return {
    headingId,
    layoutNode: {
      type: TIPTAP_LAYOUT_TYPE,
      attrs: {
        ...attrs,
        backdropColor: undefined,
        banner: { origin: 'LAYOUT', position },
        backdropPaddingTop: DEFAULT_BANNER_VERTICAL_SPACING,
        backdropPaddingBottom: DEFAULT_BANNER_VERTICAL_SPACING,
      },
      content: [
        {
          type: TIPTAP_LAYOUT_CELL_TYPE,
          attrs: {
            id: generateId(),
            colSpan: MAX_COLUMNS,
          },
          content: [
            {
              type: Node_Type.HEADING,
              attrs: {
                id: headingId,
                indentation: null,
                level: 1,
                textStyle: {
                  textAlignment: 'CENTER',
                },
                style: null,
              },
              content: [],
            },
          ],
        },
      ],
    },
  };
};

export const getImageUrl = (media: Media) =>
  getImageSrc({ file_name: media.src?.id }, undefined, {
    requiredQuality: 90,
    requiredWidth: Math.min(media.width ?? 4000, 4000),
    requiredHeight: Math.min(media.height ?? 4000, 4000),
    encAutoImageUrls: true,
  });

/** Walks up from `pos` to find a parent CARD node. Returns its ID or undefined. */
export const findParentCardId = (doc: ProseMirrorNode, pos: number): string | undefined => {
  const $pos = doc.resolve(pos);
  const parentCard = findParentNodeClosestToPos($pos, node => node.type.name === TIPTAP_CARD_TYPE);
  return parentCard?.node.attrs.id;
};

/** After a deletion, finds the CARD by ID and returns its inner start position. Falls back to 0. */
export const getCardStartPos = (tr: Transaction, cardId: string): number => {
  const card = findNodeById(tr, cardId)[0];
  return card ? card.pos + 1 : 0;
};

/** After a deletion, finds the CARD by ID and returns its inner end position. Falls back to doc end. */
export const getCardEndPos = (tr: Transaction, cardId: string): number => {
  const card = findNodeById(tr, cardId)[0];
  return card ? card.pos + card.node.nodeSize - 1 : tr.doc.content.size;
};
