import {
  Box,
  Button,
  CloseButton,
  Divider,
  FieldSet,
  FormField,
  Input,
  NumberInput,
  Tabs,
  Text,
} from '@wix/design-system';
import {
  AngledTriangleDivider,
  BlobsDivider,
  BrushDivider,
  CloudsDivider,
  DunesDivider,
  ElipseDivider,
  HillDivider,
  InvertedElipseDivider,
  LayeredElipseDivider,
  LeftWaveDivider,
  LiquidDivider,
  OpticalillusionDivider,
  PaintDivider,
  PaintScribbleDivider,
  PeaksDivider,
  PixelsDivider,
  PlantsDivider,
  RightWaveDivider,
  SemiCirclesDivider,
  SemiElipseDivider,
  StripesDivider,
  TiltDivider,
  TriangleDivider,
  WavesDivider,
} from '@wix/design-system-illustrations';
import { Adjust, ChevronLeftLarge } from '@wix/wix-ui-icons-common/lazy';
import type { FC, SVGProps } from 'react';
import React, { useContext, useMemo, useRef, useState } from 'react';

import { ModalServiceContext, RicosContext, ZIndexContext } from './../../../ricos-context/index.js';
import type {
  LayoutData_SectionDividerLayersLayerEffect,
  LayoutData_SectionDividerShape,
} from './../../../ricos-schema/next-schema/index.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { logInvariant } from './../../../_shared/log-invariant.js';
import type { PmLayoutNode } from './../../../_shared/pm-node-types.js';
import { PmNodeType } from './../../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../../_shared/use-node-attrs.js';
import {
  ColorWithOpacityInput,
  Panel,
  PanelHeader,
  SelectWithLabel,
  SliderWithInput,
  ThumbnailPicker,
  ToggleButton,
  usePanelContainerElement,
} from './../../../ui-components/index.js';

import {
  CELL_SETTINGS_COLOR_PICKER_MODAL_ID,
  getSectionDividerThumbnailDataHook,
  SECTION_DIVIDERS_BACK_BUTTON,
  SECTION_DIVIDERS_COLOR_INPUT,
  SECTION_DIVIDERS_COLOR_PICKER,
  SECTION_DIVIDERS_CUSTOMIZE_BUTTON,
  SECTION_DIVIDERS_FLIP_SELECT,
  SECTION_DIVIDERS_HEIGHT_INPUT,
  SECTION_DIVIDERS_HEIGHT_SLIDER,
  SECTION_DIVIDERS_LAYERS_COUNT_INPUT,
  SECTION_DIVIDERS_LAYERS_LAYER_EFFECT_SELECT,
  SECTION_DIVIDERS_LAYERS_OFFSET_Y_INPUT,
  SECTION_DIVIDERS_LAYERS_OFFSET_Y_SLIDER,
  SECTION_DIVIDERS_LAYERS_OFFSET_X_INPUT,
  SECTION_DIVIDERS_LAYERS_OFFSET_X_SLIDER,
  SECTION_DIVIDERS_LAYERS_TOGGLE,
  SECTION_DIVIDERS_MODAL_ID,
  SECTION_DIVIDERS_OFFSET_INPUT,
  SECTION_DIVIDERS_OFFSET_SLIDER,
  SECTION_DIVIDERS_TABS,
  SECTION_DIVIDERS_THUMBNAILS,
} from '../data-hooks.js';
import { LayoutColorPicker } from '../shared-settings-components/layout-color-picker.js';
import { useLayoutPanelClickOutside } from '../shared-settings-components/use-layout-panel-click-outside.js';
import {
  DIVIDER_HEIGHT_MAX,
  DIVIDER_HEIGHT_MIN,
  DIVIDER_LAYERS_COUNT_MAX,
  DIVIDER_LAYERS_COUNT_MIN,
  DIVIDER_LAYERS_DEFAULT_OFFSET_Y,
  DIVIDER_LAYERS_OFFSET_MAX,
  DIVIDER_LAYERS_OFFSET_MIN,
  DIVIDER_OFFSET_MAX,
  DIVIDER_OFFSET_MIN,
  DIVIDER_PRESETS,
  getDefaultDividerColor,
} from './divider-presets.js';
import classes from './section-dividers-panel-scss.js';

const NONE_VALUE = 'NONE';

const DIVIDER_ILLUSTRATIONS: Record<
  LayoutData_SectionDividerShape,
  React.ComponentType<SVGProps<SVGSVGElement>>
> = {
  ELLIPSE: ElipseDivider,
  TILT: TiltDivider,
  LIQUID: LiquidDivider,
  LEFT_WAVE: LeftWaveDivider,
  PAINT_SCRIBBLE: PaintScribbleDivider,
  INVERTED_ELLIPSE: InvertedElipseDivider,
  RIGHT_WAVE: RightWaveDivider,
  DUNES: DunesDivider,
  WAVES: WavesDivider,
  TRIANGLE: TriangleDivider,
  SEMI_ELLIPSE: SemiElipseDivider,
  PLANTS: PlantsDivider,
  LAYERED_ELLIPSE: LayeredElipseDivider,
  PIXELS: PixelsDivider,
  PAINT: PaintDivider,
  CLOUDS: CloudsDivider,
  OPTICAL_ILLUSION: OpticalillusionDivider,
  STRIPES: StripesDivider,
  BLOBS: BlobsDivider,
  SEMI_CIRCLES: SemiCirclesDivider,
  HILL: HillDivider,
  BRUSH: BrushDivider,
  PEAKS: PeaksDivider,
  ANGLED_TRIANGLE: AngledTriangleDivider,
};

const NoneThumbnail: FC<SVGProps<SVGSVGElement>> = props => (
  <svg viewBox="0 0 60 36" fill="none" {...props}>
    <rect x="0.5" y="0.5" width="59" height="35" rx="2" stroke="currentColor" opacity="0.3" />
    <line x1="4" y1="32" x2="56" y2="4" stroke="#E62214" strokeWidth="1.5" />
  </svg>
);

type DividerEdge = 'top' | 'bottom';

const EDGE_TO_ATTR_KEY = {
  top: 'topDivider',
  bottom: 'bottomDivider',
} as const;

export type SectionDividersPanelProps = {
  nodeId: string;
  referenceElement: HTMLElement | null;
};

export const SectionDividersPanel: FC<SectionDividersPanelProps> = ({
  nodeId,
  referenceElement,
}) => {
  const { t, isMobile } = useContext(RicosContext);
  const modalService = useContext(ModalServiceContext);
  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const containerEl = usePanelContainerElement();
  const { pmNodeAttrs, patchPmNodeAttrs } = useNodeAttrs(nodeId, PmNodeType.LAYOUT);
  const [edge, setEdge] = useState<DividerEdge>('bottom');
  const [view, setView] = useState<'main' | 'customize'>('main');
  const colorPickerRef = useRef<HTMLDivElement>(null);
  const logBi = useBiNext({
    modalId: SECTION_DIVIDERS_MODAL_ID,
    pluginId: 'layout',
    nodeId,
  });

  const closeModal = () => modalService.closeModal(SECTION_DIVIDERS_MODAL_ID);

  useLayoutPanelClickOutside(SECTION_DIVIDERS_MODAL_ID, referenceElement);

  // 26 entries with render-prop closures — memoized so slider drags in the
  // customize view (a re-render per tick) don't rebuild and re-translate it.
  const thumbnails = useMemo(
    () => [
      {
        value: NONE_VALUE,
        dataHook: getSectionDividerThumbnailDataHook(NONE_VALUE),
        label: t('Layout_SectionDividers_Shape_None'),
        renderBackgroundImage: ({ width, height }: { width: string; height: string }) => (
          <NoneThumbnail width={width} height={height} />
        ),
      },
      ...Object.entries(DIVIDER_PRESETS).map(([shape, shapePreset]) => {
        const Illustration = DIVIDER_ILLUSTRATIONS[shape as LayoutData_SectionDividerShape];
        return {
          value: shape,
          dataHook: getSectionDividerThumbnailDataHook(shape),
          label: t(shapePreset.labelKey),
          renderBackgroundImage: ({ width, height }: { width: string; height: string }) => (
            <Illustration
              width={width}
              height={height}
              className={edge === 'top' ? classes.topEdgeThumbnail : undefined}
            />
          ),
        };
      }),
    ],
    [t, edge]
  );

  if (!pmNodeAttrs) {
    logInvariant(new Error('Section dividers panel: node attrs not found'));
    return null;
  }

  const edgeKey = EDGE_TO_ATTR_KEY[edge];
  const divider = pmNodeAttrs[edgeKey];
  const preset = divider ? DIVIDER_PRESETS[divider.type] : undefined;
  const defaultDividerColor = getDefaultDividerColor(pmNodeAttrs);

  const patchDivider = (partial: Partial<NonNullable<PmLayoutNode['attrs']['topDivider']>>) =>
    patchPmNodeAttrs({ [edgeKey]: { ...divider, ...partial } });

  const onShapeChange = (value: string | number) => {
    if (value === NONE_VALUE) {
      patchPmNodeAttrs({ [edgeKey]: undefined });
      return;
    }
    // Switching styles keeps only the color; height/offset/flip reset to the new shape's defaults.
    const shape = value as LayoutData_SectionDividerShape;
    const { defaultLayers } = DIVIDER_PRESETS[shape];
    patchPmNodeAttrs({
      [edgeKey]: {
        type: shape,
        color: divider?.color ?? defaultDividerColor,
        ...(defaultLayers && { layers: defaultLayers }),
      },
    });
  };

  const openColorPicker = () => {
    modalService.togglePluginPanel({
      id: CELL_SETTINGS_COLOR_PICKER_MODAL_ID,
      Component: LayoutColorPicker,
      componentProps: {
        modalId: CELL_SETTINGS_COLOR_PICKER_MODAL_ID,
        nodeId,
        referenceElement: colorPickerRef.current,
        colorType: edge === 'top' ? 'topDividerColor' : 'bottomDividerColor',
        fallbackColor: divider?.color ?? defaultDividerColor,
        onValueSelected: (value: { color?: string } | undefined) =>
          patchDivider({ color: value?.color ?? defaultDividerColor }),
        allowGradient: false,
      },
      isMobile,
      positioning: {
        referenceElement: colorPickerRef.current,
        placement: 'left',
      },
      type: undefined,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      focusReturnElement: colorPickerRef.current ?? undefined,
    });
  };

  return (
    <Panel
      onCloseButtonClick={closeModal}
      dataHook={SECTION_DIVIDERS_MODAL_ID}
      maxHeight={isMobile ? undefined : 590}
    >
      {view === 'main' ? (
        <>
          <PanelHeader title={t('Layout_SectionDividers_Header')} />

          <Tabs
            dataHook={SECTION_DIVIDERS_TABS}
            size="small"
            alignment="center"
            type="uniformFull"
            minWidth={0}
            activeId={edge}
            onClick={value => {
              setEdge(value.id as DividerEdge);
              logBi({ dataHook: SECTION_DIVIDERS_TABS, value: value.id });
            }}
            items={[
              { id: 'bottom', title: t('Layout_SectionDividers_Tab_Bottom') },
              { id: 'top', title: t('Layout_SectionDividers_Tab_Top') },
            ]}
          />

          <Box direction="vertical" overflow="auto" padding="SP4" paddingTop="SP3">
            {/* @ts-expect-error CSS custom property */}
            <div style={{ '--ricos-internal-thumbnail-picker-grid-columns': 2 }}>
              <ThumbnailPicker
                dataHook={SECTION_DIVIDERS_THUMBNAILS}
                selectedValue={divider?.type ?? NONE_VALUE}
                onChange={onShapeChange}
                dataSource={thumbnails}
                size="tiny"
                tooltipAppendTo={containerEl ?? undefined}
                logBi={logBi}
              />
            </div>
          </Box>

          <Box padding="SP4" paddingTop="SP2" marginTop="auto">
            <Button
              size="medium"
              fullWidth
              priority="primary"
              prefixIcon={<Adjust />}
              disabled={!divider}
              dataHook={SECTION_DIVIDERS_CUSTOMIZE_BUTTON}
              onClick={() => {
                setView('customize');
                logBi({ dataHook: SECTION_DIVIDERS_CUSTOMIZE_BUTTON });
              }}
            >
              {t('Layout_SectionDividers_CustomizeDesign_Button')}
            </Button>
          </Box>
        </>
      ) : (
        <>
          {/* data-drag-handler keeps the modal draggable by this header, like
              the PanelHeader of the main view */}
          <div data-drag-handler="true" className={classes.customizeHeader}>
            <Box padding="SP3" gap="SP2" verticalAlign="middle">
              <CloseButton
                skin="dark"
                dataHook={SECTION_DIVIDERS_BACK_BUTTON}
                onClick={() => setView('main')}
              >
                <ChevronLeftLarge />
              </CloseButton>
              <Text size="medium" weight="bold">
                {t('Layout_SectionDividers_Customize_Header')}
              </Text>
            </Box>
          </div>

          <Box direction="vertical" overflow="auto">
            <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
              <Box paddingBottom="SP1">
                <Text size="small" weight="bold">
                  {t('Layout_SectionDividers_Customize_FillColors_Label')}
                </Text>
              </Box>

              <ColorWithOpacityInput
                label={t('Layout_SectionDividers_Customize_OverlayColor')}
                fill={{
                  type: 'color',
                  color: divider?.color ?? defaultDividerColor,
                  onChange: color => patchDivider({ color }),
                  allowTransparent: true,
                }}
                onColorPress={() => {
                  openColorPicker();
                  logBi({ dataHook: SECTION_DIVIDERS_COLOR_PICKER });
                }}
                colorPickerRef={colorPickerRef}
                inputDataHook={SECTION_DIVIDERS_COLOR_INPUT}
                fillPreviewDataHook={SECTION_DIVIDERS_COLOR_PICKER}
                zIndex={zIndex}
                logBi={logBi}
              />
            </Box>

            <Divider />

            <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
              <Box paddingBottom="SP1">
                <Text size="small" weight="bold">
                  {t('Layout_SectionDividers_Customize_Layout_Label')}
                </Text>
              </Box>

              <SliderWithInput
                label={t('Layout_SectionDividers_Customize_Height')}
                min={DIVIDER_HEIGHT_MIN}
                max={DIVIDER_HEIGHT_MAX}
                value={divider?.height ?? preset?.defaultHeight ?? 0}
                onChange={height => patchDivider({ height })}
                sliderDataHook={SECTION_DIVIDERS_HEIGHT_SLIDER}
                inputDataHook={SECTION_DIVIDERS_HEIGHT_INPUT}
                suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                tooltipAppendTo={containerEl ?? undefined}
                logBi={logBi}
              />

              {preset?.controls.includes('offsetX') && (
                <SliderWithInput
                  label={t('Layout_SectionDividers_Customize_Offset')}
                  min={DIVIDER_OFFSET_MIN}
                  max={DIVIDER_OFFSET_MAX}
                  value={divider?.offsetX ?? 0}
                  onChange={offsetX => patchDivider({ offsetX })}
                  sliderDataHook={SECTION_DIVIDERS_OFFSET_SLIDER}
                  inputDataHook={SECTION_DIVIDERS_OFFSET_INPUT}
                  suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                  tooltipAppendTo={containerEl ?? undefined}
                  logBi={logBi}
                />
              )}

              {preset?.controls.includes('flip') && (
                <SelectWithLabel<'default' | 'flipped'>
                  label={t('Layout_SectionDividers_Customize_Flip')}
                  legendPlacement="top"
                  dataHook={SECTION_DIVIDERS_FLIP_SELECT}
                  value={(divider?.flipped ?? preset?.defaultFlipped) ? 'flipped' : 'default'}
                  options={[
                    {
                      id: 'default',
                      value: t('Layout_SectionDividers_Customize_Flip_Default'),
                    },
                    {
                      id: 'flipped',
                      value: t('Layout_SectionDividers_Customize_Flip_Flipped'),
                    },
                  ]}
                  onChange={value => patchDivider({ flipped: value === 'flipped' })}
                  logBi={logBi}
                  zIndex={zIndex}
                />
              )}

              {preset?.controls.includes('layers') &&
                (preset.repeats ? (
                  // Repeat shapes mirror harmony: their layer effect is a single
                  // half-tile phase-shifted copy, so count/offset/layer effect are
                  // meaningless — expose a plain on/off toggle.
                  <ToggleButton
                    checked={(divider?.layers?.count ?? 1) > 1}
                    title={t('Layout_SectionDividers_Customize_Layers_Toggle')}
                    size="small"
                    dataHook={SECTION_DIVIDERS_LAYERS_TOGGLE}
                    onChange={() => {
                      const enabled = (divider?.layers?.count ?? 1) > 1;
                      patchDivider({
                        layers: enabled ? undefined : { count: 2 },
                      });
                      logBi({
                        dataHook: SECTION_DIVIDERS_LAYERS_TOGGLE,
                        value: String(!enabled),
                      });
                    }}
                  />
                ) : (
                  <>
                    <FormField inputWidth="100%">
                      <FieldSet
                        columns="auto 72px"
                        legendPlacement="left"
                        alignment="center"
                        legend={t('Layout_SectionDividers_Customize_Layers_Count')}
                      >
                        <div />
                        <NumberInput
                          size="small"
                          value={divider?.layers?.count ?? 1}
                          min={DIVIDER_LAYERS_COUNT_MIN}
                          max={DIVIDER_LAYERS_COUNT_MAX}
                          onChange={count => {
                            if (typeof count !== 'number') {
                              return;
                            }
                            logBi({
                              dataHook: SECTION_DIVIDERS_LAYERS_COUNT_INPUT,
                              value: count,
                            });
                            patchDivider({
                              layers: count > 1 ? { ...divider?.layers, count } : undefined,
                            });
                          }}
                          dataHook={SECTION_DIVIDERS_LAYERS_COUNT_INPUT}
                        />
                      </FieldSet>
                    </FormField>

                    {(divider?.layers?.count ?? 1) > 1 && (
                      <>
                        <SliderWithInput
                          label={t('Layout_SectionDividers_Customize_Layers_OffsetY')}
                          min={DIVIDER_LAYERS_OFFSET_MIN}
                          max={DIVIDER_LAYERS_OFFSET_MAX}
                          value={divider?.layers?.offsetY ?? DIVIDER_LAYERS_DEFAULT_OFFSET_Y}
                          onChange={offsetY =>
                            patchDivider({
                              layers: { ...divider?.layers, offsetY },
                            })
                          }
                          sliderDataHook={SECTION_DIVIDERS_LAYERS_OFFSET_Y_SLIDER}
                          inputDataHook={SECTION_DIVIDERS_LAYERS_OFFSET_Y_INPUT}
                          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                          tooltipAppendTo={containerEl ?? undefined}
                          logBi={logBi}
                        />

                        {/* Horizontal stagger is baked into the layer masks the
                            same way as the divider offset, so it needs a
                            seamlessly-wrapping path — the offsetX shapes. */}
                        {preset.controls.includes('offsetX') && (
                          <SliderWithInput
                            label={t('Layout_SectionDividers_Customize_Layers_OffsetX')}
                            min={DIVIDER_LAYERS_OFFSET_MIN}
                            max={DIVIDER_LAYERS_OFFSET_MAX}
                            value={divider?.layers?.offsetX ?? 0}
                            onChange={offsetX =>
                              patchDivider({
                                layers: { ...divider?.layers, offsetX },
                              })
                            }
                            sliderDataHook={SECTION_DIVIDERS_LAYERS_OFFSET_X_SLIDER}
                            inputDataHook={SECTION_DIVIDERS_LAYERS_OFFSET_X_INPUT}
                            suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                            tooltipAppendTo={containerEl ?? undefined}
                            logBi={logBi}
                          />
                        )}

                        <SelectWithLabel<LayoutData_SectionDividerLayersLayerEffect>
                          label={t('Layout_SectionDividers_Customize_Layers_LayerEffect')}
                          legendPlacement="top"
                          dataHook={SECTION_DIVIDERS_LAYERS_LAYER_EFFECT_SELECT}
                          value={divider?.layers?.layerEffect ?? 'CENTER'}
                          options={[
                            {
                              id: 'CENTER',
                              value: t(
                                'Layout_SectionDividers_Customize_Layers_LayerEffect_Center'
                              ),
                            },
                            {
                              id: 'FADE_TO_TOP',
                              value: t(
                                'Layout_SectionDividers_Customize_Layers_LayerEffect_FadeToTop'
                              ),
                            },
                            {
                              id: 'FADE_TO_BOTTOM',
                              value: t(
                                'Layout_SectionDividers_Customize_Layers_LayerEffect_FadeToBottom'
                              ),
                            },
                          ]}
                          onChange={layerEffect =>
                            patchDivider({
                              layers: { ...divider?.layers, layerEffect },
                            })
                          }
                          logBi={logBi}
                          zIndex={zIndex}
                        />
                      </>
                    )}
                  </>
                ))}
            </Box>
          </Box>
        </>
      )}
    </Panel>
  );
};
