import { Box, NumberInput, Popover, Slider } from '@wix/design-system';
import React, { useRef, useState } from 'react';

import { usePopoverAppendToElement } from './../ui-components-provider.js';

import classes from './input-with-slider-scss.js';

type InputWithSliderProps = {
  gradientColor?: string;
  value: number | undefined;
  onChange: (value: number) => void;
  onChangeCommit?: (finalValue: number, originalValue: number) => void;
  commitUnchanged?: boolean;
  zIndex: string | number;
  prefix?: React.ReactNode;
  suffix: React.ReactNode;
  min: number;
  max: number;
  dataHook?: string;
};

const SLIDER_WIDTH = 88;
const SLIDER_GAP = 18;
const SLIDER_PADDING = 12;

export const InputWithSlider: React.FC<InputWithSliderProps> = ({
  value,
  onChange,
  onChangeCommit,
  commitUnchanged = false,
  gradientColor,
  zIndex,
  prefix,
  suffix,
  min,
  max,
  dataHook,
}) => {
  const [isFocused, setIsFocused] = React.useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const inputWrapperRef = React.useRef<HTMLDivElement>(null);
  const popoverContentRef = React.useRef<HTMLDivElement>(null);
  const [inputValue, setInputValue] = useState<string | number>(value ?? '');
  const [sliderValue, setSliderValue] = useState<number>(value ?? min);
  const [inputKey, setInputKey] = useState(0);
  const sliderValueRef = useRef<number>(value ?? min);
  const originalValueRef = useRef<number>(value ?? min);
  const isDraggingRef = useRef(false);
  const commitTimeoutRef = useRef<number | undefined>(undefined);
  const removeDragEndListenersRef = useRef<(() => void) | undefined>(undefined);
  const appendToElement = usePopoverAppendToElement();

  const inputWrapperDimensions = inputWrapperRef.current?.getBoundingClientRect() ?? { width: 0 };
  const popoverZIndex = `calc(${zIndex} + 100)`;
  const numberInputZIndex = `calc(${popoverZIndex} + 1)`;

  React.useEffect(() => {
    const newValue = value ?? '';
    if (newValue !== inputValue) {
      setInputValue(newValue);
    }
    if (!isDraggingRef.current && typeof value === 'number') {
      setSliderValue(value);
      sliderValueRef.current = value;
    }
  }, [value]);

  React.useEffect(
    () => () => {
      removeDragEndListenersRef.current?.();
      if (commitTimeoutRef.current !== undefined) {
        window.clearTimeout(commitTimeoutRef.current);
      }
    },
    []
  );

  const handleInputWithinBounds = (data: string | undefined, shouldCommit = true) => {
    const numberValue = Math.round(Number(data));

    const valueWithinBounds =
      isNaN(numberValue) || numberValue < min ? min : numberValue > max ? max : numberValue;

    setInputValue(valueWithinBounds);
    setSliderValue(valueWithinBounds);
    sliderValueRef.current = valueWithinBounds;

    if (value !== valueWithinBounds || commitUnchanged) {
      onChange(valueWithinBounds);
      if (shouldCommit) {
        onChangeCommit?.(valueWithinBounds, originalValueRef.current);
        originalValueRef.current = valueWithinBounds;
      }
      return;
    }

    setInputKey(prev => prev + 1);
  };

  const commitSliderValue = () => {
    if (!isDraggingRef.current) {
      return;
    }

    isDraggingRef.current = false;
    const finalValue = sliderValueRef.current;
    const originalValue = originalValueRef.current;

    if (finalValue !== originalValue || commitUnchanged) {
      onChangeCommit?.(finalValue, originalValue);
    }
    originalValueRef.current = finalValue;
  };

  const scheduleSliderCommit = () => {
    if (commitTimeoutRef.current !== undefined) {
      window.clearTimeout(commitTimeoutRef.current);
    }

    commitTimeoutRef.current = window.setTimeout(() => {
      commitTimeoutRef.current = undefined;
      commitSliderValue();
    });
  };

  const handleSliderDragStart = (event: React.PointerEvent<HTMLDivElement>) => {
    removeDragEndListenersRef.current?.();
    isDraggingRef.current = true;
    originalValueRef.current = value ?? min;
    sliderValueRef.current = sliderValue;

    const ownerDocument = event.currentTarget.ownerDocument;
    const handleDocumentPointerUp = () => {
      removeDragEndListenersRef.current?.();
      scheduleSliderCommit();
    };

    removeDragEndListenersRef.current = () => {
      ownerDocument.removeEventListener('pointerup', handleDocumentPointerUp, true);
      ownerDocument.removeEventListener('pointercancel', handleDocumentPointerUp, true);
      removeDragEndListenersRef.current = undefined;
    };

    ownerDocument.addEventListener('pointerup', handleDocumentPointerUp, true);
    ownerDocument.addEventListener('pointercancel', handleDocumentPointerUp, true);
  };

  const handleSliderChange = (sliderValue: number | number[]) => {
    const newValue = typeof sliderValue === 'number' ? sliderValue : sliderValue[0];
    sliderValueRef.current = newValue;
    setSliderValue(newValue);
    setInputValue(newValue);
    onChange(newValue);
  };

  return (
    <Popover
      shown={isFocused}
      placement="right"
      moveBy={{ x: -inputWrapperDimensions.width - SLIDER_WIDTH - SLIDER_GAP - SLIDER_PADDING - 6 }}
      zIndex={popoverZIndex}
      onClickOutside={() => setIsFocused(false)}
      fixed
      appendTo={appendToElement}
    >
      <Popover.Element>
        <div
          ref={inputWrapperRef}
          style={isFocused ? { position: 'relative', zIndex: numberInputZIndex } : undefined}
        >
          <NumberInput
            inputRef={inputRef}
            key={inputKey}
            size="small"
            prefix={prefix}
            suffix={suffix}
            value={inputValue}
            min={min}
            max={max}
            onFocus={() => {
              setIsFocused(true);
            }}
            onChange={(value, stringValue) => {
              if (stringValue === '') {
                setInputValue('');
                return;
              }

              if (typeof value === 'number') {
                onChange(value);
                setInputValue(value);
              }
            }}
            onBlur={e => {
              handleInputWithinBounds(e.target.value, true);

              const nextFocusedElement = e.relatedTarget;
              const focusStayedWithinControl =
                isDraggingRef.current ||
                (nextFocusedElement instanceof Node &&
                  [inputWrapperRef.current, popoverContentRef.current].some(container =>
                    container?.contains(nextFocusedElement)
                  ));

              if (!focusStayedWithinControl) {
                setIsFocused(false);
              }
            }}
            onKeyDown={e => {
              if (['Enter', 'Escape'].includes(e.key)) {
                handleInputWithinBounds(inputRef.current?.value, true);
              }
            }}
            hideStepper
            dataHook={dataHook}
          />
        </div>
      </Popover.Element>
      <Popover.Content>
        <div ref={popoverContentRef} className={classes.sliderContainer}>
          <div style={{ width: SLIDER_WIDTH }} onPointerDown={handleSliderDragStart}>
            <Slider
              gradientColor={gradientColor}
              displayMarks={false}
              min={min}
              max={max}
              value={sliderValue}
              onChange={handleSliderChange}
              displayTooltip={false}
            />
          </div>
          <Box width={inputWrapperDimensions.width} />
        </div>
      </Popover.Content>
    </Popover>
  );
};
