import { useContext } from 'react';

import { ModalServiceContext } from './../../../ricos-context/index.js';
import {
  useClickOutside,
  usePanelContainerElement,
} from './../../../ui-components/index.js';

import { CELL_SETTINGS_COLOR_PICKER_MODAL_ID } from '../data-hooks.js';

// Close a layout side panel on outside clicks, except when the click hits the
// toolbar button that opened it (its toggle command handles closing) or while
// the layout color-picker sub-modal is open (it floats outside the panel
// container, so its clicks must not dismiss the panel underneath).
export const useLayoutPanelClickOutside = (
  modalId: string,
  referenceElement: HTMLElement | null
) => {
  const modalService = useContext(ModalServiceContext);
  const containerEl = usePanelContainerElement();

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;
      if (referenceElement?.contains(target as Node)) {
        return;
      }
      modalService.closeModal(modalId);
    },
    disable: modalService.isModalOpen(CELL_SETTINGS_COLOR_PICKER_MODAL_ID),
  });
};
