import { useContext, useMemo } from 'react';

import { EditorContext, useDevPmNodeAttrs } from './../ricos-context/index.js';
import type { PmNode } from './/pm-node-types.js';
import { createThrottle } from './../wix-rich-content-common/index.js';
import { findNodeById } from './../tiptap-editor/helpers/index.js';

export const useNodeAttrs = <T extends PmNode['type']>(
  nodeId: string,
  nodeType: T
):
  | {
      pmNodeAttrs: OneNode<T>['attrs'];
      patchPmNodeAttrs: (
        attrs: Partial<OneNode<T>['attrs']>,
        options?: { skipHistory?: boolean }
      ) => void;
    }
  | {
      pmNodeAttrs: undefined;
      patchPmNodeAttrs: undefined;
    } => {
  const { adapter } = useContext(EditorContext);
  const devPmNodeAttrs = useDevPmNodeAttrs();

  const patchPmNodeAttrs = useMemo(
    () =>
      // @ts-ignore $TSFixMe
      createThrottle((attrs: OneNode<T>['attrs'], options?: { skipHistory?: boolean }) => {
        adapter.tiptapEditor.commands.updateNodeAttrsById(nodeId, attrs, options);
      }),
    []
  );

  if (devPmNodeAttrs) {
    return {
      pmNodeAttrs: devPmNodeAttrs as OneNode<T>['attrs'],
      patchPmNodeAttrs: () => {},
    };
  }

  const tr = adapter.tiptapEditor.view.state.tr;
  const nodeWithPos = findNodeById(tr, nodeId);

  const { node } = nodeWithPos?.[0] ?? {};

  if (!node || node.type.name !== nodeType) {
    return { pmNodeAttrs: undefined, patchPmNodeAttrs: undefined };
  }

  return {
    pmNodeAttrs: node.attrs as OneNode<T>['attrs'],
    patchPmNodeAttrs,
  };
};

type OneNode<T extends U['type'], U extends { type: string } = PmNode> = U extends { type: T }
  ? U
  : never;
