import type React from 'react';
import { useEffect, useState } from 'react';

import { isInsideMockModal } from './../../_shared/is-inside-mock-modal.js';

const isEventInside = (containerRef: React.RefObject<HTMLElement>, e: PointerEvent) =>
  containerRef.current?.contains(e.target as Node) ?? false;

export function useClickOutside({
  containerRef,
  onClickOutside,
  disable,
  triggerOn,
}: {
  containerRef: React.RefObject<HTMLElement>;
  onClickOutside: (e: PointerEvent) => void;
  disable?: boolean;
  triggerOn?: 'pointerdown' | 'pointerup';
}) {
  const [isPointerDownInside, setIsPointerDownInside] = useState<boolean>(false);

  useEffect(() => {
    if (disable) {
      return;
    }

    document.addEventListener('pointerdown', handler, true);
    document.addEventListener('pointerup', handler, true);
    return () => {
      document.removeEventListener('pointerdown', handler, true);
      document.removeEventListener('pointerup', handler, true);
    };
  }, [disable, isPointerDownInside, onClickOutside]);

  function handler(e: PointerEvent) {
    const isEventInsideContainer = isEventInside(containerRef, e);
    const eventInsideSkipableContainer = isInsideMockModal(e.target as Node);

    // In pointerdown mode the press is the whole gesture: decide on it and ignore the
    // matching pointerup, so one outside press cannot notify twice and a press that
    // started on an "inside-by-exception" target cannot re-fire on release.
    if (triggerOn === 'pointerdown') {
      if (e.type === 'pointerdown' && !isEventInsideContainer && !eventInsideSkipableContainer) {
        onClickOutside(e);
      }
      return;
    }

    if (e.type === 'pointerdown') {
      setIsPointerDownInside(isEventInsideContainer);
      return;
    }

    if (
      e.type === 'pointerup' &&
      !isEventInsideContainer &&
      !isPointerDownInside &&
      !eventInsideSkipableContainer
    ) {
      onClickOutside(e);
    }
  }
}
