import type {
  LayoutData_SectionDividerLayers,
  LayoutData_SectionDividerShape,
} from './../../../ricos-schema/next-schema/index.js';
import type { PmLayoutNode } from './../../../_shared/pm-node-types.js';
import { getShapeUrl } from './../../../_shared/shape-view-renderer/get-shape-url.js';
import { svgToDataUri } from './../../../_shared/svg-to-data-uri.js';

import { hasVisibleLayoutFill, resolveLayoutFill } from '../layout-fill.js';

// Shape assets are the same wixstatic SVGs the Wix Harmony editor uses for
// section shape dividers. Harmony exposes no API for its preset list — the
// config is hardcoded in wix-private/santa-editor
// (packages/compPanels/panels/dividersPanel/dividersPresets.ts) and compiled
// into its bundles, so this table is vendored from there. Our presets map 1:1
// to harmony's preset-1..24, in order. Per-shape config:
// - defaultHeight: divider height in px when the user hasn't customized it
//   (harmony's data.height per preset)
// - repeats: split the layout width into N tiles (mask repeats horizontally)
// - defaultFlipped: the preset is authored to look best mirrored horizontally
// - controls: which optional customize controls apply to this shape, mirrored
//   from harmony's per-preset `controls` array filtered to the ones ricos
//   supports (height applies to every shape and is not listed)
//
// Shapes come in two render modes:
// - `path`: shapes that are STRETCHED to the divider band (non-uniform scaling).
//   External SVGs default to preserveAspectRatio="xMidYMid meet", which a CSS
//   mask cannot override — the shape would letterbox (float centered, shrink)
//   instead of stretching. These are inlined as data-URI SVGs with
//   preserveAspectRatio="none". All of them share the 1920x300 viewBox and are
//   tiny single-path files (~300 bytes each).
// - `svgId`: shapes drawn at their NATURAL aspect ratio (tiled horizontally,
//   mask-size `auto 100%`), where letterboxing never kicks in. These stay as
//   remote wixstatic URLs — some are large (up to ~130KB) and not worth bundling.
export type DividerControl = 'flip' | 'offsetX' | 'layers';

export type DividerPreset = {
  labelKey: string;
  defaultHeight: number;
  controls: readonly DividerControl[];
  repeats?: number;
  defaultFlipped?: boolean;
  // the shape is authored to be inserted with a layers effect already on
  defaultLayers?: LayoutData_SectionDividerLayers;
} & ({ path: string; svgId?: never } | { svgId: string; path?: never });

// Dividers over a backdrop default to the document background color so they
// read as a cutout of the backdrop; without a backdrop they need a visible
// non-background shade.
export const getDefaultDividerColor = (
  attrs: Pick<PmLayoutNode['attrs'], 'backdrop' | 'backdropColor' | 'backdropImage'>
): '$theme-color-1' | '$theme-color-7' =>
  attrs.backdropImage ||
  hasVisibleLayoutFill(resolveLayoutFill(attrs.backdrop, attrs.backdropColor))
    ? '$theme-color-1'
    : '$theme-color-7';
export const DIVIDER_HEIGHT_MIN = 0;
export const DIVIDER_HEIGHT_MAX = 500;
export const DIVIDER_OFFSET_MIN = 0;
export const DIVIDER_OFFSET_MAX = 500;
// Layer defaults mirror harmony's: toggling layers on there produces 4 total
// layers spaced 20px apart, centered.
export const DIVIDER_LAYERS_COUNT_MIN = 1;
export const DIVIDER_LAYERS_COUNT_MAX = 4;
export const DIVIDER_LAYERS_OFFSET_MIN = 0;
export const DIVIDER_LAYERS_OFFSET_MAX = 100;
export const DIVIDER_LAYERS_DEFAULT_OFFSET_Y = 20;

