// All inlined divider shapes are authored on the same canvas.
const DIVIDER_SVG_VIEWBOX = '0 0 1920 300';
const DIVIDER_SVG_CANVAS_WIDTH = 1920;

// Offset is baked into the mask as a canvas-space phase shift (rather than a
// px mask-position) so the shifted shape still stretches edge-to-edge with the
// layout: resizing smushes/stretches the shape while the same shape points stay
// pinned to the layout edges, instead of the pattern sliding past them. The
// shifted path leaves the window [0, shift] empty, so a second copy translated
// one canvas back fills it — the shape wraps seamlessly (every offsetX-enabled
// path starts and ends at the same y on both canvas edges).
const toStretchableMaskUrl = (path: string, canvasShift: number) => {
  const paths =
    canvasShift === 0
      ? `<path d="${path}"/>`
      : `<path d="${path}" transform="translate(${canvasShift})"/><path d="${path}" transform="translate(${
          canvasShift - DIVIDER_SVG_CANVAS_WIDTH
        })"/>`;
  return `url("${svgToDataUri(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${DIVIDER_SVG_VIEWBOX}" preserveAspectRatio="none">${paths}</svg>`
  )}")`;
};

export type DividerMaskVars = {
  mask: string;
  maskSize: string;
  maskRepeat: string;
  maskPosition: string | null;
};

// offsetX means "screen px at a 1920px-wide layout", scaling with layout
// width. One canvas renders as one tile of width/repeats, so the shift is
// multiplied by repeats to keep the on-screen shift uniform across shapes.
// Double-mod keeps negative offsets in [0, canvas).
const getCanvasShift = (offsetX: number, repeats: number) =>
  (((offsetX * repeats) % DIVIDER_SVG_CANVAS_WIDTH) + DIVIDER_SVG_CANVAS_WIDTH) %
  DIVIDER_SVG_CANVAS_WIDTH;

export const getDividerMaskVars = (
  shape: LayoutData_SectionDividerShape,
  offsetX = 0
): DividerMaskVars => {
  const preset = DIVIDER_PRESETS[shape];
  if (preset.path) {
    const canvasShift = getCanvasShift(offsetX, preset.repeats ?? 1);
    return {
      mask: toStretchableMaskUrl(preset.path, canvasShift),
      // stretch to fill the whole band, or tile it into N stretched tiles
      maskSize: preset.repeats ? `calc(100% / ${preset.repeats}) 100%` : '100% 100%',
      maskRepeat: preset.repeats ? 'repeat-x' : 'no-repeat',
      maskPosition: null,
    };
  }
  // Natural-aspect shapes: tile horizontally at the band height. Their tiles
  // never stretch on resize, so a plain px offset can't slide — keep it as a
  // mask-position.
  return {
    mask: `url(${getShapeUrl({ id: preset.svgId })})`,
    maskSize: 'auto 100%',
    maskRepeat: 'repeat-x',
    maskPosition: offsetX ? `${offsetX}px 0` : null,
  };
};

export type DividerLayer = DividerMaskVars & {
  height: string;
  opacity: number;
};

// Expands a divider into its stack of layer elements, replicating harmony's
// layers effect. Returned in PAINT ORDER: deepest (faintest) layer first, the
// base shape LAST so it composites on top. All math is bottom-edge-relative;
// the top divider reuses it through the CSS scaleY(-1) mirror.
//
// Only `path` presets ever opt into layers (mirrors harmony — every preset
// with a `layers` control there is one of our inlined shapes), so layer masks
// are always fully baked data-URI SVGs.
export const getDividerLayers = (divider: {
  type: LayoutData_SectionDividerShape;
  height?: number;
  offsetX?: number;
  layers?: LayoutData_SectionDividerLayers;
}): DividerLayer[] => {
  const preset = DIVIDER_PRESETS[divider.type];
  const height = divider.height ?? preset.defaultHeight;
  const base = getDividerMaskVars(divider.type, divider.offsetX);
  const count = Math.min(
    Math.max(divider.layers?.count ?? 1, DIVIDER_LAYERS_COUNT_MIN),
    DIVIDER_LAYERS_COUNT_MAX
  );

  if (count <= 1 || !preset.controls.includes('layers')) {
    return [{ ...base, height: `${height}px`, opacity: 1 }];
  }

  // Repeat shapes mirror harmony's repeat-mode layer effect: a single extra
  // copy phase-shifted half a tile horizontally — layer offsets/effect and any
  // count beyond "on" have no meaning there. The shift is computed in canvas
  // units so fractional tile widths (e.g. PEAKS' 11 tiles) stay exact.
  if (preset.repeats && preset.path) {
    const phaseShift =
      (getCanvasShift(divider.offsetX ?? 0, preset.repeats) + DIVIDER_SVG_CANVAS_WIDTH / 2) %
      DIVIDER_SVG_CANVAS_WIDTH;
    return [
      {
        ...base,
        mask: toStretchableMaskUrl(preset.path, phaseShift),
        height: `${height}px`,
        opacity: 0.5,
      },
      { ...base, height: `${height}px`, opacity: 1 },
    ];
  }

  const layersOffsetY = divider.layers?.offsetY ?? DIVIDER_LAYERS_DEFAULT_OFFSET_Y;
  // Horizontal stagger between layers is baked into each layer's mask the same
  // way as the divider-level offsetX, so it only works on shapes whose paths
  // wrap seamlessly — the ones with the offsetX control.
  const layersOffsetX = preset.controls.includes('offsetX') ? (divider.layers?.offsetX ?? 0) : 0;
  const layerEffect = divider.layers?.layerEffect ?? 'CENTER';

  return Array.from({ length: count }, (_, index) => {
    const depth = count - 1 - index;
    const extra = depth * layersOffsetY;
    const layerMask =
      layersOffsetX && depth
        ? getDividerMaskVars(divider.type, (divider.offsetX ?? 0) + depth * layersOffsetX)
        : base;
    // FADE_TO_BOTTOM: the shape stretches taller into the section, so the faded
    // copies fan out above the base and descend to the edge. FADE_TO_TOP: it
    // shrinks toward the edge inside the original band (solid filler below), so
    // the faded copies hug the top of the band. CENTER: it keeps its height and
    // a solid filler bar pushes it away from the edge.
    const shapeHeight =
      layerEffect === 'FADE_TO_BOTTOM'
        ? height + extra
        : layerEffect === 'FADE_TO_TOP'
          ? Math.max(height - extra, 0)
          : height;
    const fillerHeight =
      layerEffect === 'FADE_TO_BOTTOM'
        ? 0
        : layerEffect === 'FADE_TO_TOP'
          ? Math.min(extra, height)
          : extra;
    const opacity = 1 / (depth + 1);

    if (fillerHeight === 0) {
      return { ...layerMask, height: `${shapeHeight}px`, opacity };
    }
    // Two-part mask: the shape pinned away from the edge plus a solid bar
    // (a black gradient) at the edge. The default mask-composite (add/union)
    // paints both from one background fill, so alpha colors don't double-blend.
    return {
      mask: `${layerMask.mask}, linear-gradient(#000, #000)`,
      maskSize: `100% ${shapeHeight}px, 100% ${fillerHeight}px`,
      maskRepeat: 'no-repeat, no-repeat',
      maskPosition: '0 0, left bottom',
      height: `${shapeHeight + fillerHeight}px`,
      opacity,
    };
  });
};
